// Package testutil exposes helpers for tests inside the apps/sdk-go
// module. It resolves the monorepo workspace root and the absolute
// paths to the cross-language fixtures generated by spec 037.
//
// The helper lives under internal/ so it is not part of the customer-
// facing API surface. Note: Go's toolchain ignores directories named
// "testdata/" during regular builds — this package therefore cannot
// live there (research §R5).
package testutil

import (
	"fmt"
	"os"
	"path/filepath"
	"sync"
)

// workspaceRoot walks up from os.Getwd() looking for the pnpm-workspace.yaml
// sentinel that anchors the monorepo root. The result is cached via
// sync.OnceValue so repeated calls across tests in a session are free.
var workspaceRoot = sync.OnceValue(func() string {
	cwd, err := os.Getwd()
	if err != nil {
		panic(fmt.Errorf("testutil: os.Getwd failed: %w", err))
	}
	for dir := cwd; ; dir = filepath.Dir(dir) {
		if _, err := os.Stat(filepath.Join(dir, "pnpm-workspace.yaml")); err == nil {
			return dir
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			panic(fmt.Errorf(
				"testutil: could not find pnpm-workspace.yaml above %q "+
					"(tests must run from within the monorepo)", cwd,
			))
		}
	}
})

// WorkspaceRoot returns the absolute path to the monorepo root (the
// directory containing pnpm-workspace.yaml).
func WorkspaceRoot() string {
	return workspaceRoot()
}

// ParityCorpusPath is the absolute path to the 58-tuple parity corpus
// generated by packages/test-fixtures-sdk-parity (spec 037).
func ParityCorpusPath() string {
	return filepath.Join(
		WorkspaceRoot(),
		"packages", "test-fixtures-sdk-parity", "fixtures", "parity-corpus.json",
	)
}

// ParityConfigsPath is the absolute path to the canonical configs JSON
// (each record carries the wire config + an overridesMap).
func ParityConfigsPath() string {
	return filepath.Join(
		WorkspaceRoot(),
		"packages", "test-fixtures-sdk-parity", "fixtures", "parity-configs.json",
	)
}

