// UpstreamCorpusDir is the absolute path to the vendored ConfigCat
// evaluation conformance corpus (spec 117 / spec 119 §R7). It holds the
// testmatrix*.csv matrices, the evaluationlog/ scenarios, the
// comparison_*.json conversion/trimming fixtures, and content-by-key.json.
// Provenance-pinned to configcat/go-sdk@08c4882 v9 (see
// fixtures/upstream/PROVENANCE.md); never re-vendored.
func UpstreamCorpusDir() string {
	return filepath.Join(
		WorkspaceRoot(),
		"packages", "test-fixtures-sdk-parity", "fixtures", "upstream",
	)
}
